# Break My Fix finding 1, generated by Tracefix: ordinal returns a wrong value.
# Property (docstring): Numbers ending in 11, 12 or 13 take th
# Quote: A number ending in 11, 12 or 13 takes "th"
# Run it with pytest: it fails for as long as the code breaks this property.

from standings.ordinal import ordinal


def test_break_my_fix_1() -> None:
    n = 111
    # The property applies to this input: isinstance(n, int) and not isinstance(n, bool) and n >= 1 and n % 100 in (11, 12, 13)
    result = ordinal(n=n)
    assert result == (str(n) + 'th')
